AssistantMessageToolRequest(name='create', tool_call_id='tooluse_z2NUxrZSGFT0JtkRkcWsGp', arguments={'file_text': 'const form = document.getElementById('contactForm');
const fullNameInput = document.getElementById('fullName');
const emailInput = document.getElementById('email');
const phoneInput = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

const validators = {
  fullName: {
    validate: (value) => value.trim().length > 0,
    message: 'Full name is required.'
  },
  email: {
    validate: (value) => {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(value);
    },
    message: (value) => {
      if (value.trim().length === 0) return 'Email is required.';
      return 'Please enter a valid email address.';
    }
  },
  phone: {
    validate: (value) => {
      if (value.trim().length === 0) return true;
      const phoneRegex = /^[\d\s\-\(\)]+$/.test(value) && value.replace(/\D/g, '').length === 10;
      return phoneRegex;
    },
    message: 'Please enter a valid phone number (10 digits).'
  }
};

function showError(inputElement, message) {
  const errorDiv = document.getElementById(inputElement.id + 'Error');
  if (errorDiv) {
    errorDiv.textContent = message;
    inputElement.setAttribute('aria-invalid', 'true');
  }
}

function clearError(inputElement) {
  const errorDiv = document.getElementById(inputElement.id + 'Error');
  if (errorDiv) {
    errorDiv.textContent = '';
    inputElement.setAttribute('aria-invalid', 'false');
  }
}

function validateField(inputElement) {
  const fieldName = inputElement.name;
  const validator = validators[fieldName];

  if (!validator) return true;

  const value = inputElement.value;
  const isValid = validator.validate(value);

  if (!isValid) {
    const message = typeof validator.message === 'function' 
      ? validator.message(value) 
      : validator.message;
    showError(inputElement, message);
    return false;
  } else {
    clearError(inputElement);
    return true;
  }
}

fullNameInput.addEventListener('blur', () => validateField(fullNameInput));
emailInput.addEventListener('blur', () => validateField(emailInput));
phoneInput.addEventListener('blur', () => validateField(phoneInput));

fullNameInput.addEventListener('input', () => {
  if (fullNameInput.getAttribute('aria-invalid') === 'true') {
    validateField(fullNameInput);
  }
});

emailInput.addEventListener('input', () => {
  if (emailInput.getAttribute('aria-invalid') === 'true') {
    validateField(emailInput);
  }
});

phoneInput.addEventListener('input', () => {
  if (phoneInput.getAttribute('aria-invalid') === 'true') {
    validateField(phoneInput);
  }
});

form.addEventListener('submit', (e) => {
  e.preventDefault();

  const fullNameValid = validateField(fullNameInput);
  const emailValid = validateField(emailInput);
  const phoneValid = validateField(phoneInput);

  if (fullNameValid && emailValid && phoneValid) {
    showSuccessMessage();
    form.reset();
    successMessage.setAttribute('aria-hidden', 'false');
    setTimeout(() => {
      successMessage.setAttribute('aria-hidden', 'true');
    }, 5000);
  } else {
    const firstInvalid = document.querySelector('[aria-invalid="true"]');
    if (firstInvalid) {
      firstInvalid.focus();
    }
  }
});

function showSuccessMessage() {
  console.log('Form submitted successfully!');
  console.log({
    fullName: fullNameInput.value,
    email: emailInput.value,
    phone: phoneInput.value
  });
}
